async function api(request,env,profile){await env.DB.prepare(schema).run();const u=new URL(request.url),manager=profile.role==="manager";
if(request.method==="GET"){let owner=u.searchParams.get("owner_id"),q="SELECT id,owner_id AS ownerId,owner_name AS ownerName,module,dealer,note,material,category,width,height,qty,date,created_at AS createdAt FROM secure_cuts",bind=[];if(manager&&owner){q+=" WHERE owner_id=?";bind.push(owner)}else if(!manager){q+=" WHERE owner_id=?";bind.push(profile.user_id)}q+=" ORDER BY created_at DESC";let st=env.DB.prepare(q),r=bind.length?await st.bind(...bind).all():await st.all();return out(r.results||[])}
if(request.method==="POST"){const p=await request.json(),raw=Array.isArray(p.items)?p.items:[];if(!raw.length)return out({error:"Ma’lumot yo‘q"},400);for(const x of raw){let mod=manager?String(x.module||"laser"):profile.department;if(!["external","laser","print"].includes(mod))continue;const id=Date.now()+"-"+crypto.randomUUID(),dealer=String(x.dealer||""),note=String(x.note||"");if(!(dealer||note)||!x.material||!(+x.qty>0))continue;await env.DB.prepare("INSERT INTO secure_cuts(id,owner_id,owner_name,owner_email,module,dealer,note,material,category,width,height,qty,date,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)").bind(id,profile.user_id,profile.full_name,profile.email,mod,dealer,note,String(x.material),x.category||"material",+x.width||0,+x.height||0,+x.qty,x.date||new Date().toISOString().slice(0,10),new Date().toISOString()).run()}return out({ok:true},201)}
if(request.method==="DELETE"){let p={};try{p=await request.json()}catch{}const dealer=p.dealer||u.searchParams.get("dealer"),mod=p.module||u.searchParams.get("module")||profile.department;if(dealer){let q=manager?"DELETE FROM secure_cuts WHERE dealer=? AND module=? AND category!='palasa'":"DELETE FROM secure_cuts WHERE dealer=? AND module=? AND owner_id=? AND category!='palasa'",args=manager?[dealer,mod]:[dealer,mod,profile.user_id];await env.DB.prepare(q).bind(...args).run();return out({ok:true})}if(Array.isArray(p.ids)){for(const id of p.ids){let q=manager?"DELETE FROM secure_cuts WHERE id=?":"DELETE FROM secure_cuts WHERE id=? AND owner_id=?",args=manager?[String(id)]:[String(id),profile.user_id];await env.DB.prepare(q).bind(...args).run()}return out({ok:true})}return out({error:"Tanlanmagan"},400)}return out({error:"Method"},405)}
export default{async fetch(request,env){const p=new URL(request.url).pathname;if(p==="/")return new Response(servedPage,{headers:{"content-type":"text/html; charset=utf-8"}});if(p.startsWith("/api/")){let profile=await identity(request);if(!profile)return out({error:"Kirish talab qilinadi"},401);if(p==="/api/me")return out(profile);if(p==="/api/employees")return employees(request,profile);if(p==="/api/cuts")return api(request,env,profile)}return new Response("Not found",{status:404})}};
